# SuperCalc.OG frozen manifest: the stock RPI_PICO2_W manifest plus the splash modules.
# tools/build_supercalc.sh passes this file as FROZEN_MANIFEST (paths are relative to
# this directory). sc_splash_data.py is generated by tools/make_splash.py.
include("$(BOARD_DIR)/manifest.py")
module("sc_splash.py")
module("sc_splash_data.py")
# PicoCalc boot splash (20261115h): random amber image at power-up, no SuperCALC branding.
# pc_splash_a..d.py are generated by tools/make_splash.py from splash/amber/*.png.
module("pc_splash.py")
module("pc_splash_a.py")
module("pc_splash_b.py")
module("pc_splash_c.py")
module("pc_splash_d.py")
